package org.brightstats.stats;
import java.util.*;import java.nio.file.*;import com.google.gson.*;
public final class RegularizedChecks {
 static int checks;static void require(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
 static SemModel.Model model(){return new SemModel.Model(List.of("X","Y"),new int[]{0,1},new double[2][2],new double[][]{{1,0},{0,1}},new double[2],List.of(new SemModel.Parameter("Slope",List.of(new SemModel.Location(SemModel.Kind.DIRECTED,1,0)),.1,1)));}
 static RegularizedSem.Options options(double mixing){return new RegularizedSem.Options(List.of(new RegularizedSem.Target("Slope",0,1)),new double[]{0,.03,.1,.3},mixing,3,3,7171,3000,1e-8,1e-6);}
 public static void main(String[] args)throws Exception{Path out=Path.of(args[0]);Files.createDirectories(out);double[][] data=new double[180][2];Random rng=new Random(88271);for(var row:data){row[0]=rng.nextGaussian();row[1]=.2*row[0]+rng.nextGaussian();}var model=model();double xx=0,xy=0;for(var row:data){xx+=row[0]*row[0]/data.length;xy+=row[0]*row[1]/data.length;}JsonArray optima=new JsonArray();var gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().create();for(double mixing:new double[]{0,.5,1})for(double lambda:new double[]{0,.03,.1,.3}){var result=RegularizedSem.optimize(data,model,options(mixing),lambda);double truth=Math.copySign(Math.max(0,Math.abs(xy)-lambda*mixing),xy)/(xx+lambda*(1-mixing));require(result.converged()&&Math.abs(result.theta()[0]-truth)<1e-7,"Known Gaussian regression elastic-net optimum");JsonObject value=new JsonObject();value.addProperty("mixing",mixing);value.addProperty("lambda",lambda);value.add("result",gson.toJsonTree(result));optima.add(value);}
 int[] progress={0};var fit=RegularizedSem.fit(data,model,options(.5),step->{if(step!=++progress[0])throw new AssertionError("False fit-count progress");});var again=RegularizedSem.fit(data,model,options(.5),null);require(gson.toJson(fit).equals(gson.toJson(again)),"Seeded nested selection reproducibility");require(fit.completedFits()==52&&progress[0]==52,"Exact planned fit accounting");Set<Integer> heldOut=new HashSet<>();for(var fold:fit.outerValidation()){require(Collections.disjoint(fold.trainingRows(),fold.heldOutRows()),"No outer leakage");require(fold.trainingRows().size()+fold.heldOutRows().size()==180,"Every source row accounted for per fold");for(int row:fold.heldOutRows())require(heldOut.add(row),"Held-out rows occur in one outer fold only");}require(heldOut.size()==180,"Outer held-out coverage");var altered=Matrices.copy(data);for(int row:fit.outerValidation().getFirst().heldOutRows())altered[row-1][1]+=100;var alteredFit=RegularizedSem.fit(altered,model,options(.5),null);require(fit.outerValidation().getFirst().selectedLambda()==alteredFit.outerValidation().getFirst().selectedLambda()&&Arrays.equals(fit.outerValidation().getFirst().estimates(),alteredFit.outerValidation().getFirst().estimates()),"Changing outer outcomes cannot change their training selection/refit");Thread.currentThread().interrupt();try{RegularizedSem.fit(data,model,options(.5),null);throw new AssertionError("Regularization cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}double[][] missing=Matrices.copy(data);missing[0][0]=Double.NaN;try{RegularizedSem.fit(missing,model,options(.5),null);throw new AssertionError("Missing data silently replaced");}catch(IllegalArgumentException expected){checks++;}
 JsonObject record=new JsonObject();record.add("data",gson.toJsonTree(data));record.add("fit",gson.toJsonTree(fit));record.add("optima",optima);record.addProperty("checks",checks);Files.writeString(out.resolve("cases.json"),new GsonBuilder().setPrettyPrinting().create().toJson(record));System.out.println("Regularized SEM checks: "+checks);}
}
